{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Clinical PET with [11C]LY2795050 showed favorable brain uptake in humans, directly demonstrating CNS access for a biaryl-ether amide closely related to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "PET imaging in rhesus macaques showed [11C]PBR28 entered the brain with ~0.1 %ID/cc, supporting CNS penetration for a pyridine-ether amide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "18F-LY2459989 exhibited high brain uptake in nonhuman primates with fast, reversible kinetics, supporting CNS access for a related antagonist scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "JNJ16259685 crossed the BBB rapidly and occupied central mGlu1 receptors in rats, demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Compound 7q had a rat brain/plasma ratio of 1.66, indicating good CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "VU6043653 had a rat brain:plasma Kp of 1.68, classified as excellent CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Tetrahydropalmatine was detected in rat CSF, confirming passage across the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "18F-FEDAC showed >1 %ID/g brain radioactivity in mice, indicating rapid BBB entry.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In control rats, irinotecan and SN-38 brain interstitium concentrations were <1% of plasma by microdialysis, indicating poor baseline CNS penetration for that large camptothecin.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to have meaningful CNS access. Multiple high-transfer direct measurements in humans, nonhuman primates, rats, and mice demonstrate brain uptake, CSF detection, and brain/plasma ratios ≥1 for structurally related CNS penetrants. The single contradictory microdialysis record for irinotecan reflects a large camptothecin with known efflux liability and is outweighed by the consistent positive evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule; prediction relies on high-transfer analogues.",
    "The contradictory irinotecan record raises a possible efflux liability, but the query's smaller size and lipophilic amine/amide features are more consistent with the positive CNS penetrant set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

